import pytest

from inventory.models import Inventory, InsufficientStock, InventoryError, Item


@pytest.fixture
def inv():
    return Inventory([
        Item("w-1", "Widget", 250, quantity=10, reorder_level=4, tags=["small"]),
        Item("g-9", "Gadget", 1999, quantity=3, reorder_level=3),
    ])


def test_sku_is_normalized(inv):
    assert "W-1" in inv
    assert inv.get(" w-1 ").name == "Widget"


def test_receive_and_remove_update_quantity(inv):
    assert inv.receive("W-1", 5) == 15
    assert inv.remove("W-1", 12) == 3
    assert [m.delta for m in inv.history("W-1")] == [10, 5, -12]


def test_remove_more_than_available_raises(inv):
    with pytest.raises(InsufficientStock) as info:
        inv.remove("G-9", 4)
    assert info.value.available == 3


def test_low_stock_orders_by_urgency(inv):
    inv.remove("W-1", 7)  # 3 left, level 4 -> -1
    skus = [i.sku for i in inv.low_stock()]
    assert skus == ["W-1", "G-9"]


def test_unknown_sku(inv):
    with pytest.raises(InventoryError):
        inv.get("nope")


def test_json_roundtrip(inv):
    inv.receive("G-9", 2)
    clone = Inventory.from_json(inv.to_json())
    assert clone.total_value_cents() == inv.total_value_cents()
    assert len(clone.history()) == len(inv.history())


