#!/usr/bin/env python3
"""Compute per-column summary statistics for a CSV file."""

import argparse
import csv
import statistics
import sys


def numeric_columns(rows, header):
    cols = {name: [] for name in header}
    for row in rows:
        for name, cell in zip(header, row):
            try:
                cols[name].append(float(cell))
            except ValueError:
                cols[name] = None if cols[name] == [] else cols[name]
                break
    return {k: v for k, v in cols.items() if v}


def describe(values):
    values = sorted(values)
    n = len(values)
    q = statistics.quantiles(values, n=4) if n >= 2 else [values[0]] * 3
    return {
        "n": n,
        "min": values[0],
        "q1": q[0],
        "median": q[1],
        "q3": q[2],
        "max": values[-1],
        "mean": statistics.fmean(values),
        "stdev": statistics.stdev(values) if n > 1 else 0.0,
    }


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("path", nargs="?", default="-")
    ap.add_argument("--delimiter", default=",")
    ap.add_argument("--precision", type=int, default=3)
    args = ap.parse_args()

    stream = sys.stdin if args.path == "-" else open(args.path, newline="")
    with stream:
        reader = csv.reader(stream, delimiter=args.delimiter)
        header = next(reader)
        cols = numeric_columns(reader, header)

    for name, values in cols.items():
        stats = describe(values)
        line = "  ".join(f"{k}={v:.{args.precision}f}" if k != "n" else f"n={v}"
                         for k, v in stats.items())
        print(f"{name:>16}: {line}")


if __name__ == "__main__":
    main()


