"""A tiny priority task scheduler using a binary heap."""

import heapq
import itertools
import time
from typing import Callable, Optional


class Scheduler:
    def __init__(self, clock: Callable[[], float] = time.monotonic) -> None:
        self._clock = clock
        self._heap = []
        self._counter = itertools.count()
        self._cancelled = set()

    def call_later(self, delay: float, fn: Callable[[], None], priority: int = 0) -> int:
        task_id = next(self._counter)
        when = self._clock() + delay
        heapq.heappush(self._heap, (when, priority, task_id, fn))
        return task_id

    def cancel(self, task_id: int) -> None:
        self._cancelled.add(task_id)

    def next_deadline(self) -> Optional[float]:
        while self._heap and self._heap[0][2] in self._cancelled:
            _, _, tid, _ = heapq.heappop(self._heap)
            self._cancelled.discard(tid)
        return self._heap[0][0] if self._heap else None

    def run_pending(self) -> int:
        """Run every task whose deadline has passed; return how many ran."""
        ran = 0
        now = self._clock()
        while True:
            deadline = self.next_deadline()
            if deadline is None or deadline > now:
                return ran
            _, _, tid, fn = heapq.heappop(self._heap)
            try:
                fn()
            except Exception as exc:  # keep the loop alive
                print(f"task {tid} failed: {exc!r}")
            ran += 1


def _demo():
    fake_now = [0.0]
    sched = Scheduler(clock=lambda: fake_now[0])
    log = []
    sched.call_later(2, lambda: log.append("b"))
    sched.call_later(1, lambda: log.append("a"))
    doomed = sched.call_later(1.5, lambda: log.append("never"))
    sched.cancel(doomed)
    fake_now[0] = 3
    assert sched.run_pending() == 2
    assert log == ["a", "b"], log
    print("scheduler ok")


if __name__ == "__main__":
    _demo()


/* ---------------------------------------------------------------------------
 * File: vec.h / vec.c  -- a growable array of ints
 * ------------------------------------------------------------------------- */
#ifndef VEC_H
#define VEC_H

#include <stddef.h>

typedef struct {
    int    *data;
    size_t  len;
    size_t  cap;
} vec_t;

void   vec_init(vec_t *v);
void   vec_free(vec_t *v);
int    vec_push(vec_t *v, int value);          /* 0 on success, -1 on OOM */
int    vec_pop(vec_t *v, int *out);            /* 0 on success, -1 if empty */
void   vec_sort(vec_t *v);

#endif /* VEC_H */

#include <stdlib.h>
#include <string.h>

void vec_init(vec_t *v) {
    v->data = NULL;
    v->len = 0;
    v->cap = 0;
}

void vec_free(vec_t *v) {
    free(v->data);
    vec_init(v);
}

int vec_push(vec_t *v, int value) {
    if (v->len == v->cap) {
        size_t new_cap = v->cap ? v->cap * 2 : 8;
        int *p = realloc(v->data, new_cap * sizeof *p);
        if (!p) return -1;           /* old buffer is still valid */
        v->data = p;
        v->cap = new_cap;
    }
    v->data[v->len++] = value;
    return 0;
}

int vec_pop(vec_t *v, int *out) {
    if (v->len == 0) return -1;
    *out = v->data[--v->len];
    return 0;
}

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);        /* avoids overflow from x - y */
}

void vec_sort(vec_t *v) {
    qsort(v->data, v->len, sizeof *v->data, cmp_int);
}


/* ---------------------------------------------------------------------------
 * File: hashmap.c -- open addressing, linear probing, string keys
 * ------------------------------------------------------------------------- */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char    *key;       /* NULL = empty, TOMBSTONE = deleted */
    int      value;
} slot_t;

typedef struct {
    slot_t *slots;
    size_t  cap;        /* always a power of two */
    size_t  used;       /* live entries */
    size_t  filled;     /* live entries + tombstones */
} map_t;

static char TOMBSTONE_KEY[] = "<deleted>";
#define TOMBSTONE TOMBSTONE_KEY

/* FNV-1a, 64-bit */
static uint64_t hash_str(const char *s) {
    uint64_t h = 1469598103934665603ULL;
    for (; *s; s++) {
        h ^= (unsigned char)*s;
        h *= 1099511628211ULL;
    }
    return h;
}

static int map_init(map_t *m, size_t cap) {
    m->slots = calloc(cap, sizeof(slot_t));
    if (!m->slots) return -1;
    m->cap = cap;
    m->used = m->filled = 0;
    return 0;
}

static slot_t *map_find(const map_t *m, const char *key, int for_insert) {
    size_t mask = m->cap - 1;
    size_t i = hash_str(key) & mask;
    slot_t *first_tomb = NULL;
    for (;;) {
        slot_t *s = &m->slots[i];
        if (s->key == NULL)
            return (for_insert && first_tomb) ? first_tomb : s;
        if (s->key == TOMBSTONE) {
            if (!first_tomb) first_tomb = s;
        } else if (strcmp(s->key, key) == 0) {
            return s;
        }
        i = (i + 1) & mask;
    }
}

static int map_grow(map_t *m) {
    map_t bigger;
    if (map_init(&bigger, m->cap * 2) != 0) return -1;
    for (size_t i = 0; i < m->cap; i++) {
        slot_t *s = &m->slots[i];
        if (s->key && s->key != TOMBSTONE) {
            slot_t *d = map_find(&bigger, s->key, 1);
            *d = *s;
            bigger.used++;
            bigger.filled++;
        }
    }
    free(m->slots);
    *m = bigger;
    return 0;
}

int map_put(map_t *m, const char *key, int value) {
    /* keep load factor (including tombstones) under 70% */
    if ((m->filled + 1) * 10 > m->cap * 7 && map_grow(m) != 0) return -1;
