        double r;
        if (calc_eval(argv[i], &r, err, sizeof err) == 0)
            printf("%s = %.10g\n", argv[i], r);
        else
            fprintf(stderr, "%s: error: %s\n", argv[i], err);
    }
    return 0;
}
