 * File: hashmap.c -- open addressing, linear probing, string keys
 * ------------------------------------------------------------------------- */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char    *key;       /* NULL = empty, TOMBSTONE = deleted */
    int      value;
} slot_t;

typedef struct {
    slot_t *slots;
    size_t  cap;        /* always a power of two */
    size_t  used;       /* live entries */
    size_t  filled;     /* live entries + tombstones */
} map_t;

static char TOMBSTONE_KEY[] = "<deleted>";
#define TOMBSTONE TOMBSTONE_KEY

/* FNV-1a, 64-bit */
static uint64_t hash_str(const char *s) {
    uint64_t h = 1469598103934665603ULL;
    for (; *s; s++) {
        h ^= (unsigned char)*s;
        h *= 1099511628211ULL;
    }
    return h;
}

static int map_init(map_t *m, size_t cap) {
    m->slots = calloc(cap, sizeof(slot_t));
    if (!m->slots) return -1;
    m->cap = cap;
    m->used = m->filled = 0;
    return 0;
}

static slot_t *map_find(const map_t *m, const char *key, int for_insert) {
    size_t mask = m->cap - 1;
    size_t i = hash_str(key) & mask;
    slot_t *first_tomb = NULL;
    for (;;) {
        slot_t *s = &m->slots[i];
        if (s->key == NULL)
            return (for_insert && first_tomb) ? first_tomb : s;
        if (s->key == TOMBSTONE) {
            if (!first_tomb) first_tomb = s;
        } else if (strcmp(s->key, key) == 0) {
            return s;
        }
        i = (i + 1) & mask;
    }
}

static int map_grow(map_t *m) {
    map_t bigger;
    if (map_init(&bigger, m->cap * 2) != 0) return -1;
    for (size_t i = 0; i < m->cap; i++) {
        slot_t *s = &m->slots[i];
        if (s->key && s->key != TOMBSTONE) {
            slot_t *d = map_find(&bigger, s->key, 1);
            *d = *s;
            bigger.used++;
            bigger.filled++;
        }
    }
    free(m->slots);
    *m = bigger;
    return 0;
}

int map_put(map_t *m, const char *key, int value) {
    /* keep load factor (including tombstones) under 70% */
    if ((m->filled + 1) * 10 > m->cap * 7 && map_grow(m) != 0) return -1;
    slot_t *s = map_find(m, key, 1);
    if (s->key == NULL || s->key == TOMBSTONE) {
        char *copy = strdup(key);
        if (!copy) return -1;
        if (s->key == NULL) m->filled++;
        s->key = copy;
        m->used++;
    }
    s->value = value;
    return 0;
}

int map_get(const map_t *m, const char *key, int *out) {
    slot_t *s = map_find(m, key, 0);
    if (s->key == NULL) return 0;
    *out = s->value;
    return 1;
}

int map_del(map_t *m, const char *key) {
    slot_t *s = map_find(m, key, 0);
    if (s->key == NULL) return 0;
    free(s->key);
    s->key = TOMBSTONE;
    m->used--;
    return 1;
}

int main(void) {
    map_t m;
    if (map_init(&m, 8) != 0) return 1;
    const char *words[] = {"alpha", "beta", "gamma", "delta", "epsilon",
                           "zeta", "eta", "theta", "iota", "kappa"};
    for (int i = 0; i < 10; i++) map_put(&m, words[i], i * i);
    map_del(&m, "gamma");
    int v;
    printf("delta -> %d\n", map_get(&m, "delta", &v) ? v : -1);
    printf("gamma present: %d\n", map_get(&m, "gamma", &v));
    printf("used=%zu cap=%zu\n", m.used, m.cap);
    return 0;
}


/* ---------------------------------------------------------------------------
 * File: calc.c -- recursive descent parser for arithmetic expressions
 *
 * Grammar:
 *   expr   := term   (('+' | '-') term)*
 *   term   := factor (('*' | '/' | '%') factor)*
 *   factor := ('-' | '+') factor | power
 *   power  := atom ('^' factor)?          -- right associative
 *   atom   := NUMBER | IDENT '(' expr ')' | '(' expr ')'
 * ------------------------------------------------------------------------- */
#include <ctype.h>
#include <math.h>
#include <setjmp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    const char *src;
    const char *p;
    jmp_buf     err;
    char        msg[96];
} parser_t;

static void fail(parser_t *ps, const char *what) {
    snprintf(ps->msg, sizeof ps->msg, "%s at column %d", what, (int)(ps->p - ps->src) + 1);
    longjmp(ps->err, 1);
}

static void skip_ws(parser_t *ps) {
    while (isspace((unsigned char)*ps->p)) ps->p++;
}

static int accept(parser_t *ps, char c) {
    skip_ws(ps);
    if (*ps->p == c) { ps->p++; return 1; }
    return 0;
}

static double parse_expr(parser_t *ps);

static double parse_atom(parser_t *ps) {
    skip_ws(ps);
    if (accept(ps, '(')) {
        double v = parse_expr(ps);
        if (!accept(ps, ')')) fail(ps, "expected ')'");
        return v;
    }
    if (isdigit((unsigned char)*ps->p) || *ps->p == '.') {
        char *end;
        double v = strtod(ps->p, &end);
        ps->p = end;
        return v;
    }
    if (isalpha((unsigned char)*ps->p)) {
        char name[16];
        size_t n = 0;
        while (isalnum((unsigned char)*ps->p) && n + 1 < sizeof name)
            name[n++] = *ps->p++;
        name[n] = '\0';
        if (!accept(ps, '(')) fail(ps, "expected '(' after function name");
        double arg = parse_expr(ps);
        if (!accept(ps, ')')) fail(ps, "expected ')'");
        if (!strcmp(name, "sqrt")) return sqrt(arg);
        if (!strcmp(name, "sin"))  return sin(arg);
        if (!strcmp(name, "cos"))  return cos(arg);
        if (!strcmp(name, "ln"))   return log(arg);
        if (!strcmp(name, "abs"))  return fabs(arg);
        fail(ps, "unknown function");
    }
    fail(ps, "unexpected character");
    return 0.0; /* not reached */
}

static double parse_factor(parser_t *ps);

static double parse_power(parser_t *ps) {
    double base = parse_atom(ps);
    if (accept(ps, '^')) return pow(base, parse_factor(ps));
    return base;
}

static double parse_factor(parser_t *ps) {
    if (accept(ps, '-')) return -parse_factor(ps);
    if (accept(ps, '+')) return parse_factor(ps);
    return parse_power(ps);
}

static double parse_term(parser_t *ps) {
    double v = parse_factor(ps);
    for (;;) {
        if (accept(ps, '*')) v *= parse_factor(ps);
        else if (accept(ps, '/')) {
            double d = parse_factor(ps);
            if (d == 0.0) fail(ps, "division by zero");
            v /= d;
        } else if (accept(ps, '%')) {
            double d = parse_factor(ps);
            if (d == 0.0) fail(ps, "modulo by zero");
            v = fmod(v, d);
        } else return v;
    }
}

static double parse_expr(parser_t *ps) {
    double v = parse_term(ps);
    for (;;) {
        if (accept(ps, '+')) v += parse_term(ps);
        else if (accept(ps, '-')) v -= parse_term(ps);
        else return v;
    }
}

int calc_eval(const char *text, double *result, char *errbuf, size_t errlen) {
    parser_t ps = { .src = text, .p = text };
    if (setjmp(ps.err)) {
        snprintf(errbuf, errlen, "%s", ps.msg);
        return -1;
    }
    double v = parse_expr(&ps);
    skip_ws(&ps);
    if (*ps.p != '\0') fail(&ps, "trailing input");
    *result = v;
    return 0;
}

