#include <cassert>
#include <iostream>
#include <numeric>
#include <thread>
#include <vector>

#include "ring_buffer.hpp"

int main() {
    constexpr int kCount = 1'000'000;
    SpscRing<int, 1024> ring;

    std::thread producer([&] {
        for (int i = 0; i < kCount; ++i) {
            while (!ring.push(i)) { /* spin until there is room */ }
        }
    });

    long long sum = 0;
    int received = 0;
    int expected = 0;
    while (received < kCount) {
        if (auto v = ring.pop()) {
            assert(*v == expected++);  // FIFO order must be preserved
            sum += *v;
            ++received;
        }
    }
    producer.join();

    const long long want = static_cast<long long>(kCount - 1) * kCount / 2;
    std::cout << "sum=" << sum << " expected=" << want
              << (sum == want ? " OK" : " MISMATCH") << '\n';
    return sum == want ? 0 : 1;
}


