// File: bst.cpp -- an unbalanced binary search tree with iterative traversal
// ---------------------------------------------------------------------------
#include <functional>
#include <iostream>
#include <memory>
#include <stack>
#include <string>

template <typename K, typename V>
class Bst {
    struct Node {
        K key;
        V value;
        std::unique_ptr<Node> left, right;
        Node(K k, V v) : key(std::move(k)), value(std::move(v)) {}
    };

public:
    bool insert(K key, V value) {
        std::unique_ptr<Node>* cur = &root_;
        while (*cur) {
            if (key < (*cur)->key)       cur = &(*cur)->left;
            else if ((*cur)->key < key)  cur = &(*cur)->right;
            else { (*cur)->value = std::move(value); return false; }
        }
        *cur = std::make_unique<Node>(std::move(key), std::move(value));
        ++size_;
        return true;
    }

    const V* find(const K& key) const {
        const Node* n = root_.get();
        while (n) {
            if (key < n->key)      n = n->left.get();
            else if (n->key < key) n = n->right.get();
            else return &n->value;
        }
        return nullptr;
    }

    // In-order traversal without recursion, so deep trees cannot blow the stack.
    void for_each(const std::function<void(const K&, const V&)>& fn) const {
        std::stack<const Node*> pending;
        const Node* n = root_.get();
        while (n || !pending.empty()) {
            while (n) { pending.push(n); n = n->left.get(); }
            n = pending.top();
            pending.pop();
            fn(n->key, n->value);
            n = n->right.get();
        }
    }

    std::size_t size() const { return size_; }

    int height() const { return height(root_.get()); }

private:
    static int height(const Node* n) {
        if (!n) return 0;
        return 1 + std::max(height(n->left.get()), height(n->right.get()));
    }

    std::unique_ptr<Node> root_;
    std::size_t size_ = 0;
};

int main() {
    Bst<std::string, int> tree;
    for (const char* w : {"pear", "apple", "quince", "banana", "cherry", "fig"})
        tree.insert(w, static_cast<int>(std::string(w).size()));
    tree.for_each([](const std::string& k, int v) {
        std::cout << k << " (" << v << ")\n";
    });
    std::cout << "height=" << tree.height() << " size=" << tree.size() << '\n';
    if (const int* p = tree.find("cherry")) std::cout << "cherry -> " << *p << '\n';
}


