#include <cstdio>
#include <cuda_runtime.h>

#define CUDA_CHECK(expr)                                                       \
    do {                                                                       \
        cudaError_t err__ = (expr);                                            \
        if (err__ != cudaSuccess) {                                            \
            std::fprintf(stderr, "%s:%d: %s\n", __FILE__, __LINE__,            \
                         cudaGetErrorString(err__));                           \
            std::exit(1);                                                      \
        }                                                                      \
    } while (0)

// y = a*x + y, grid-stride loop so any grid size handles any n.
__global__ void saxpy(int n, float a, const float* __restrict__ x,
                      float* __restrict__ y) {
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < n;
         i += gridDim.x * blockDim.x) {
        y[i] = fmaf(a, x[i], y[i]);
    }
}

// Sum reduction: each warp reduces with shuffles, then warp leaders combine
// through shared memory. Launch with blockDim.x a multiple of 32, <= 1024.
__global__ void block_sum(const float* __restrict__ in, float* __restrict__ out,
                          int n) {
    __shared__ float partial[32];
    float v = 0.0f;
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < n;
         i += gridDim.x * blockDim.x) {
        v += in[i];
    }
#pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        v += __shfl_down_sync(0xffffffffu, v, off);
    }
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (lane == 0) partial[warp] = v;
    __syncthreads();

    if (warp == 0) {
        const int nwarps = blockDim.x >> 5;
        v = (lane < nwarps) ? partial[lane] : 0.0f;
#pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            v += __shfl_down_sync(0xffffffffu, v, off);
        }
        if (lane == 0) atomicAdd(out, v);
    }
}

// Tiled matrix transpose. The +1 padding on the shared tile avoids bank
// conflicts when threads in a warp read down a column.
constexpr int TILE = 32;

__global__ void transpose(const float* __restrict__ in, float* __restrict__ out,
                          int rows, int cols) {
    __shared__ float tile[TILE][TILE + 1];

    int x = blockIdx.x * TILE + threadIdx.x;
    int y = blockIdx.y * TILE + threadIdx.y;
    if (x < cols && y < rows) tile[threadIdx.y][threadIdx.x] = in[y * cols + x];
    __syncthreads();

    x = blockIdx.y * TILE + threadIdx.x;   // swapped block indices
    y = blockIdx.x * TILE + threadIdx.y;
    if (x < rows && y < cols) out[y * rows + x] = tile[threadIdx.x][threadIdx.y];
}

int main() {
    const int n = 1 << 22;
    float *x, *y, *sum;
    CUDA_CHECK(cudaMallocManaged(&x, n * sizeof(float)));
    CUDA_CHECK(cudaMallocManaged(&y, n * sizeof(float)));
    CUDA_CHECK(cudaMallocManaged(&sum, sizeof(float)));
    for (int i = 0; i < n; ++i) { x[i] = 1.0f; y[i] = 2.0f; }
    *sum = 0.0f;

    saxpy<<<256, 256>>>(n, 3.0f, x, y);          // y becomes 5.0 everywhere
    block_sum<<<128, 256>>>(y, sum, n);
    CUDA_CHECK(cudaDeviceSynchronize());

    std::printf("sum = %.1f (expected %.1f)\n", *sum, 5.0f * n);
    cudaFree(x); cudaFree(y); cudaFree(sum);
    return 0;
}


