#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# File: scripts/rotate_logs.sh -- compress old logs, delete ancient ones
# ---------------------------------------------------------------------------
set -euo pipefail

LOG_DIR="${1:-/var/log/myapp}"
COMPRESS_AFTER_DAYS="${COMPRESS_AFTER_DAYS:-2}"
DELETE_AFTER_DAYS="${DELETE_AFTER_DAYS:-30}"
DRY_RUN="${DRY_RUN:-0}"

log() { printf '[%s] %s\n' "$(date +%H:%M:%S)" "$*" >&2; }

run() {
    if [[ "$DRY_RUN" == "1" ]]; then
        log "dry-run: $*"
    else
        "$@"
    fi
}

[[ -d "$LOG_DIR" ]] || { log "no such directory: $LOG_DIR"; exit 1; }

# Compress anything older than N days that is not already gzipped.
while IFS= read -r -d '' f; do
    log "compressing $f"
    run gzip -9 -- "$f"
done < <(find "$LOG_DIR" -type f -name '*.log' -mtime +"$COMPRESS_AFTER_DAYS" -print0)

# Remove compressed logs past retention.
count=0
while IFS= read -r -d '' f; do
    run rm -f -- "$f"
    count=$((count + 1))
done < <(find "$LOG_DIR" -type f -name '*.log.gz' -mtime +"$DELETE_AFTER_DAYS" -print0)

log "removed $count old archive(s)"


